CREATE TABLE IF NOT EXISTS lending_records (id TEXT PRIMARY KEY, person TEXT NOT NULL, phone TEXT NOT NULL DEFAULT '', usd REAL NOT NULL DEFAULT 0, iqd REAL NOT NULL DEFAULT 0, fib REAL NOT NULL DEFAULT 0, super_qi REAL NOT NULL DEFAULT 0, direction TEXT NOT NULL CHECK(direction IN ('green','red')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX IF NOT EXISTS idx_lending_created ON lending_records(created_at);
